// CSD_RATIONALE_BEGIN
// Analysis of 52% best-attempt failures:
// (A) The 5-step unconstrained preamble may cause the model to emit partial SQL before <<,
//     anchoring Phase 3 to suboptimal query patterns (SQL "commitment" in free text).
// (B) GroupBoostedConstrainedStep boost=6.0 is insufficient to overcome the LM's strong
//     prior for short alias tokens (e.g., "t", "ca") over full schema names like "teacher".
//     Raising to 10.0 makes schema tokens overwhelmingly preferred in the soft boost.
// (C) No cap on Phase 3 → the 895-token whitespace/tab loop in complex queries
//     (third failure: SUM(CASE followed by endless \t) consumes entire budget.
//
// Targeted changes from best attempt (52%, syntax 99%):
//   1. Reduce preamble from 5 to 2 unconstrained steps (cut pre-span SQL commitment risk)
//   2. Increase boost: GroupBoostedConstrainedStep(10.0) instead of 6.0
//   3. Cap Phase 3 at 150 constrained steps, then hand off to CloseSpanWithinBudget
//   4. Keep all other structure identical to the 52% best
//
// Structure:
//   Phase 1: ≤2 unconstrained steps → emit "SQL: " or "SQL"
//   Phase 2: Force << if not yet inside span
//   Phase 3: Hard-constrained SQL loop, cap 150 steps, boost 10.0
//   Phase 4: CloseSpanWithinBudget(min(remaining,100)) fallback close
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble loop (guard !insideConstrainedOut):
//   insideConstrainedOut flips true only via RenderedEndsWith; we set
//   currentConstrainedOut := [] which is parser-valid by method precondition.
//   EOS keeps insideConstrainedOut=false (implication vacuously true).
//
// Phase 2 OpenConstrainedSpan (only if !insideConstrainedOut):
//   Helper sets currentConstrainedOut := []; IsValidPrefix([]) by precondition. ✓
//
// Phase 3 constrained loop:
//   IsCompletePrefix branch: CloseConstrainedSpan sets insideConstrainedOut := false
//     (implication vacuously true), clears currentConstrainedOut := []. ✓
//   Normal branch: GroupBoostedConstrainedStep hard-masks to parser-valid tokens + EOS;
//     AppendConstrainedToken extends currentConstrainedOut by one valid token,
//     preserving IsValidPrefix by the parser extension contract. ✓
//   EOS+complete branch: CloseConstrainedSpan sets insideConstrainedOut := false. ✓
//   EOS+incomplete branch: break without state change; invariant holds by induction. ✓
//
// Phase 4 CloseSpanWithinBudget:
//   Postcondition guarantees insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep increments steps by 1, appends ≤1 token (0 on EOS,
//   1 otherwise). Invariant preserved each iteration.
//
// Phase 2: OpenConstrainedSpan increments steps by 1, appends exactly 1 "<<" token.
//   Net 1:1; invariant preserved. ✓
//
// Phase 3: Each iteration increments steps by exactly 1 for the generation helper call
//   (GroupBoostedConstrainedStep or the CloseConstrainedSpan that replaces the guard).
//   Visible output grows by at most 1 token per step (one constrained token OR ">>" on
//   close). The optional second CloseConstrainedSpan in the EOS branch is gated by
//   steps < maxSteps, so the extra +1 is always within budget. Cap phase3Limit ≤ maxSteps
//   ensures loop exits with steps ≤ maxSteps. ✓
//
// Phase 4: CloseSpanWithinBudget postcondition |generatedOut| ≤ |generated| + budget.
//   steps grows by closeBudget ≤ remaining = maxSteps - steps_before.
//   Final steps ≤ maxSteps; cost = steps ≤ maxSteps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. Do not use table aliases or column aliases. Place the complete SQL query between << and >>. No explanation, no markdown.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 2 steps) to let model emit "SQL: " prefix
while steps < maxSteps && steps < 2 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard constrained control with schema-token boosting
// Cap at 150 steps to prevent whitespace/tab loops in complex queries
var phase3Limit: nat := if steps + 150 <= maxSteps then steps + 150 else maxSteps;

while steps < phase3Limit && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant phase3Limit <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase3Limit - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    break;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.GroupBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 10.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 4: If span still open and budget remains, use CloseSpanWithinBudget as fallback
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 100 {
    closeBudget := remaining;
  } else {
    closeBudget := 100;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

